referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const a = d.nodes.findIndex((n) => n.id === d.start),
    b = d.nodes.findIndex((n) => n.id === d.end);
  return d.nodes
    .slice(a + 1, b)
    .map((n) => n.text)
    .join("");
}

